import csv
import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def parcels(p):
    full,rest=divmod(p['count'],p['capacity'])
    return [p['capacity']]*full+([rest] if rest else [])

def zones(p):
    matches=[k for k in p['zones'] if p['postal'].startswith(k)]
    return p['zones'][max(matches,key=len)] if matches else None

def billable(p):
    return max(p['actual'],p['dimensional'])//1000

